// Auto-MOC from frontmatter `down:`
// Output is plain text (no links) as a nested bullet list.

dv.container.classList.add("moc-tree");

const root = dv.current();
const seen = new Set();

function asPage(ref) {
  if (!ref) return null;

  // Dataview Link objects usually have .path
  if (typeof ref === "object" && ref.path) return dv.page(ref.path);

  // Sometimes refs come through as page-like objects
  if (typeof ref === "object" && ref.file && ref.file.path) return dv.page(ref.file.path);

  // Strings: "A", "Folder/A", etc.
  if (typeof ref === "string") {
    const s = ref.replace(/^\[\[/, "").replace(/\]\]$/, "");
    return dv.page(s);
  }

  return dv.page(String(ref));
}

function childrenOf(page) {
  if (!page) return [];
  const down = page.down;
  if (!down) return [];

  const arr = Array.isArray(down) ? down : [down];
  const pages = arr.map(asPage).filter(Boolean);
  return pages;
}

function addNode(parentUl, page) {
  if (!page || !page.file) return;

  const key = page.file.path || page.file.name;
  if (seen.has(key)) return;
  seen.add(key);

  const li = document.createElement("li");
  li.textContent = page.file.name; // plain text, not a link
  parentUl.appendChild(li);

  const kids = childrenOf(page);
  if (kids.length > 0) {
    const ul = document.createElement("ul");
    li.appendChild(ul);
    for (let i = 0; i < kids.length; i++) addNode(ul, kids[i]);
  }
}

// Render
dv.container.innerHTML = "";
const topUl = document.createElement("ul");
dv.container.appendChild(topUl);
addNode(topUl, root);

